const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};
const received = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expected = 'sha256=' + (item.computedSignature || '');
if (!received || received !== expected) throw new Error('Signature HMAC invalide');
for (const field of ['runId','workflowId','entityType','entityId','workspaceId','userId','callbackUrl']) {
  if (!body[field]) throw new Error('Champ requis manquant : ' + field);
}
if (body.workflowId !== 'intel-040-workspace-diagnostic') throw new Error('workflowId invalide');
if (body.entityType !== 'workspace' || body.entityId !== body.workspaceId) throw new Error('Le diagnostic requiert le workspace comme entité');
const input = body.input || {};
if (input.diagnosticType !== 'workspace_diagnostic') throw new Error('diagnosticType invalide');
if (typeof input.asOfDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(input.asOfDate)) throw new Error('asOfDate invalide');
return [{ json: { runId: body.runId, workflowId: body.workflowId, workspaceId: body.workspaceId, userId: body.userId, callbackUrl: body.callbackUrl, asOfDate: input.asOfDate } }];

const response = $input.first().json;
const upstream = $('Assemble Prompt').item.json;
const candidateTexts = [];
if (Array.isArray(response.content)) {
  for (const block of response.content) {
    if (block && block.type === 'text' && typeof block.text === 'string') candidateTexts.push(block.text);
  }
}
if (typeof response.output_text === 'string') candidateTexts.push(response.output_text);
if (typeof response.text === 'string') candidateTexts.push(response.text);
const raw = candidateTexts.map((value) => value.trim()).find(Boolean);
if (!raw) throw new Error('Le LLM a renvoyé un contenu vide');
function compactSnippet(value) {
  return String(value).replace(/\s+/g, ' ').trim().slice(0, 300);
}
function stripMarkdownFence(value) {
  const text = String(value).trim();
  const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  return fenced ? fenced[1].trim() : text;
}
function parseJsonObject(value) {
  const text = stripMarkdownFence(value);
  try {
    return JSON.parse(text);
  } catch (directError) {
    let depth = 0;
    let start = -1;
    let inString = false;
    let escaped = false;
    for (let index = 0; index < text.length; index += 1) {
      const char = text[index];
      if (start === -1) {
        if (char === '{') {
          start = index;
          depth = 1;
        }
        continue;
      }
      if (inString) {
        if (escaped) escaped = false;
        else if (char === '\\') escaped = true;
        else if (char === '"') inString = false;
        continue;
      }
      if (char === '"') inString = true;
      else if (char === '{') depth += 1;
      else if (char === '}') {
        depth -= 1;
        if (depth === 0) {
          const candidate = text.slice(start, index + 1);
          try {
            return JSON.parse(candidate);
          } catch (candidateError) {
            throw new Error('Réponse LLM non-JSON : ' + candidateError.message + ' | extrait=' + compactSnippet(candidate));
          }
        }
      }
    }
    throw new Error('Réponse LLM non-JSON : ' + directError.message + ' | extrait=' + compactSnippet(text));
  }
}
const parsed = parseJsonObject(raw);
if (parsed.schema_version !== 1) throw new Error('schema_version doit valoir 1');
if (typeof parsed.executiveSummary !== 'string' || !parsed.executiveSummary.trim()) throw new Error('executiveSummary invalide');
for (const key of ['correlations','priorities','watchList','strengths']) {
  if (!Array.isArray(parsed[key])) throw new Error(key + ' doit être un tableau');
}
const axesAllowed = new Set(['commerce','delivery','finance','team','recruitment']);
const severityAllowed = new Set(['critical','warning','opportunity']);
for (const correlation of parsed.correlations) {
  if (!correlation.id || !correlation.title || !correlation.narrative) throw new Error('Corrélation incomplète');
  if (!Array.isArray(correlation.axes) || correlation.axes.some((axis) => !axesAllowed.has(axis))) throw new Error('Axes de corrélation invalides');
  if (!severityAllowed.has(correlation.severity)) throw new Error('Sévérité invalide');
  if (!Array.isArray(correlation.evidenceRefs)) throw new Error('evidenceRefs invalide');
}
const asOf = new Date(upstream.asOfDate + 'T12:00:00Z');
const day = asOf.getUTCDay() || 7;
const monday = new Date(asOf);
monday.setUTCDate(asOf.getUTCDate() - day + 1);
const sunday = new Date(monday);
sunday.setUTCDate(monday.getUTCDate() + 6);
const fmt = new Intl.DateTimeFormat('fr-FR', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });
const periodLabel = 'Semaine du ' + fmt.format(monday) + ' au ' + fmt.format(sunday);
const diagnostic = {
  schema_version: 1,
  generatedAt: new Date().toISOString(),
  periodLabel,
  executiveSummary: parsed.executiveSummary.trim(),
  correlations: parsed.correlations,
  priorities: parsed.priorities.map((priority, index) => ({ ...priority, rank: index + 1 })),
  watchList: parsed.watchList,
  strengths: parsed.strengths,
};
return [{ json: { ...upstream, diagnostic, llmUsage: { inputTokens: response.usage && response.usage.input_tokens || null, outputTokens: response.usage && response.usage.output_tokens || null, model: response.model || 'claude-sonnet-5' } } }];

const data = $input.first().json;
const diagnostic = data.diagnostic;
const qaFlags = [];
const correlationIds = new Set(diagnostic.correlations.map((item) => item.id));
const crossAxes = diagnostic.correlations.every((item) => new Set(item.axes || []).size >= 2);
qaFlags.push({ check: 'correlations_cross_axes', passed: crossAxes, detail: crossAxes ? 'Toutes les corrélations croisent plusieurs axes' : 'Une corrélation est mono-axe' });
function getPath(root, path) {
  return path.split('.').reduce((value, key) => value && typeof value === 'object' ? value[key] : undefined, root);
}
const evidenceOk = diagnostic.correlations.every((item) => Array.isArray(item.evidenceRefs) && item.evidenceRefs.length > 0 && item.evidenceRefs.every((ref) => typeof ref.metric === 'string' && getPath(data.context, ref.metric) !== undefined));
qaFlags.push({ check: 'evidence_refs_present', passed: evidenceOk, detail: evidenceOk ? 'Toutes les preuves pointent vers le contexte' : 'Preuve absente ou chemin inconnu' });
function normalizeNumber(token) {
  const normalized = String(token).replace(/\s/g, '').replace(',', '.').replace(/^\+/, '');
  const numeric = Number(normalized);
  return Number.isFinite(numeric) ? String(numeric) : normalized;
}
function isIdentifierKey(key) {
  return key === 'id' || /Id$/.test(key) || key === 'relatedCorrelationIds';
}
function collectContextNumbers(value, target, key = '') {
  if (typeof value === 'number' && Number.isFinite(value)) target.add(normalizeNumber(value));
  else if (typeof value === 'string' && !isIdentifierKey(key)) {
    (value.match(/[-+]?\d+(?:[\s.,]\d+)*/g) || []).forEach((token) => target.add(normalizeNumber(token)));
  } else if (Array.isArray(value)) {
    value.forEach((item) => collectContextNumbers(item, target, key));
  } else if (value && typeof value === 'object') {
    Object.entries(value).forEach(([childKey, item]) => collectContextNumbers(item, target, childKey));
  }
}
const structuralTextKeys = new Set(['schema_version','generatedAt','periodLabel','rank','id','metric','relatedCorrelationIds']);
function generatedTexts(value, target, key = '') {
  if (typeof value === 'string' && !structuralTextKeys.has(key)) target.push(value);
  else if (Array.isArray(value)) value.forEach((item) => generatedTexts(item, target, key));
  else if (value && typeof value === 'object') Object.entries(value).forEach(([childKey, item]) => {
    generatedTexts(item, target, childKey);
  });
}
const allowedNumbers = new Set();
collectContextNumbers(data.context, allowedNumbers);
const texts = [];
generatedTexts(diagnostic, texts);
const citedNumbers = texts.flatMap((text) => text.match(/[-+]?\d+(?:[\s.,]\d+)*/g) || []).map(normalizeNumber);
const inventedNumbers = [...new Set(citedNumbers.filter((token) => !allowedNumbers.has(token)))];
qaFlags.push({ check: 'no_invented_numbers', passed: inventedNumbers.length === 0, detail: inventedNumbers.length === 0 ? 'Aucun nombre non sourcé' : 'Nombres non sourcés : ' + inventedNumbers.join(', ') });
const limitsOk = diagnostic.correlations.length <= 4 && diagnostic.priorities.length <= 3 && diagnostic.watchList.length <= 3 && diagnostic.strengths.length <= 3;
qaFlags.push({ check: 'max_items_respected', passed: limitsOk, detail: diagnostic.correlations.length + ' corrélations, ' + diagnostic.priorities.length + ' priorités, ' + diagnostic.watchList.length + ' signaux, ' + diagnostic.strengths.length + ' forces' });
const prioritiesLinked = diagnostic.priorities.every((priority) => Array.isArray(priority.relatedCorrelationIds) && priority.relatedCorrelationIds.length > 0 && priority.relatedCorrelationIds.every((id) => correlationIds.has(id)));
qaFlags.push({ check: 'priorities_linked', passed: prioritiesLinked, detail: prioritiesLinked ? 'Toutes les priorités sont reliées' : 'Priorité orpheline détectée' });
return [{ json: { ...data, qaFlags } }];

const data = $input.first().json;
const diagnostic = data.diagnostic;
const lines = ['# Diagnostic du centre de profit', '', diagnostic.executiveSummary, '', '## Corrélations'];
for (const item of diagnostic.correlations) lines.push('- ' + item.title + ' — ' + item.narrative);
lines.push('', '## Priorités');
for (const item of diagnostic.priorities) lines.push(item.rank + '. ' + item.action + ' — ' + item.rationale);
const callbackBody = {
  runId: data.runId,
  phase: 1,
  resultType: 'workspace_diagnostic',
  status: 'succeeded',
  contentJson: diagnostic,
  contentText: lines.join('\n'),
  title: 'Diagnostic du centre de profit — ' + diagnostic.periodLabel,
  modelProvider: 'anthropic',
  modelUsed: data.llmUsage && data.llmUsage.model || 'claude-sonnet-5',
  tokensInput: data.llmUsage && data.llmUsage.inputTokens || null,
  tokensOutput: data.llmUsage && data.llmUsage.outputTokens || null,
  contextSnapshot: data.context,
  sourceRefs: [{ entityType: 'workspace', entityId: data.workspaceId, label: 'Snapshot du centre de profit' }],
  qaFlags: data.qaFlags,
};
return [{ json: { callbackUrl: data.callbackUrl, rawBody: JSON.stringify(callbackBody) } }];

const errItem = $input.first().json;
let validated = {};
try { validated = $('Validate Request').item.json; } catch (error) {}
let errorMessage = 'Erreur inconnue dans intel-040-workspace-diagnostic';
if (errItem && errItem.error) errorMessage = typeof errItem.error === 'string' ? errItem.error : errItem.error.message || JSON.stringify(errItem.error);
else if (errItem && errItem.message) errorMessage = errItem.message;
const callbackBody = { runId: validated.runId || null, phase: 1, resultType: 'workspace_diagnostic', status: 'failed', contentJson: {}, errorMessage };
return [{ json: { callbackUrl: validated.callbackUrl || null, rawBody: JSON.stringify(callbackBody) } }];
